head.script:
scwin.gridView2_oneditkeyup = function(info) {
    if (info.keyCode === 13) {
        dataList1.insertRow();
    }
};
scwin.fireDbClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.__isBackground = function() {
    var color = WebSquare.wUnit.getJq("#gridView2_cell_0_2").css("background-color");
    if (color.indexOf("rgb") < 0) {
        return color == "#fca73c";
    }
    return color == "rgb(252, 167, 60)";
}
scwin.setVal = function() {
    scwin.fireDbClick('gridView2_cell_0_1');
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#G_gridView2__col2').simulate('key-combo', {
        combo: 'ENTER'
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView2_cell_0_1').click()");
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify  1.  edit모드로 변경된다.
    //1. Change to edit mode.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView2__col2').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 그 상태에서 EnterKey를 누른다.
    //2. In that state, press EnterKey.
    //WebSquare.wUnit.addCommand("set", "");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2.  readonly인 name3항목필드로 포커스가 이동되고 row가 추가된다.(이전에는 다음필드가 readonly일경우 row가 추가되지 않았음)
    //2. The focus is moved to the readonly name3 item field and the row is added. (Previously the row was not added if the next field was readonly.)
    WebSquare.wUnit.addCommand("assert", "scwin.__isBackground()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView2_body_tbody tr').not('.w2grid_hidedRow').length == 4", "true");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 15-Mar-2018
    //End unitTest
}
